// tree_lime.hpp - the animated oak trees: 24 sway frames per tree, 6 looks. The grass around the roots is not part of these frames,
// it is a separate sprite (tree_grass.hpp) that each look points to (OakVar::grass).
// Frames come from the tree_*_grass_sway.gif files (the baked-in grey ground shadow was removed, the game draws its own).
// Each frame is a grid of letters: '.' = clear, a-p = index into that tree's palette.
#pragma once
#include "core/gfx.hpp"
#include "art/tree_grass.hpp"

constexpr int OAK_FRAMES = 24;
constexpr float OAK_FPS = 8.f;  // 24 frames in a 3 second loop
constexpr int OAK_VARIANTS = 6;
// How much of a tree's leafy top the tree next to it may cover (worldgen.hpp, World::thinTrees): 0 = not at all, 0.3 = about a third,
// 1 = no limit. A tree straight behind another covers a lot, so it must stand far back; a tree shifted to the side covers less and may
// stand closer, so neighbours end up staggered in rows. A tree that would break the limit is left out. Lower = fewer trees.
constexpr float TREE_OVERLAP = 0.3f;

