static const u32 OAK_P0[8] = {HEX(0x0d4000), HEX(0x198000), HEX(0x32c000), HEX(0x4bff00), HEX(0x95604f), HEX(0x6b4439), HEX(0x402922), HEX(0xc07b66)};  // lime
static const u32 OAK_P1[8] = {HEX(0x052e1e), HEX(0x0e5834), HEX(0x1b8044), HEX(0x2fa84f), HEX(0x95604f), HEX(0x6b4439), HEX(0x402922), HEX(0xc07b66)};  // deep
static const u32 OAK_P2[8] = {HEX(0x20541e), HEX(0x4c9c2c), HEX(0x80ce38), HEX(0xbef45a), HEX(0x95604f), HEX(0x6b4439), HEX(0x402922), HEX(0xc07b66)};  // soft
static const u32 OAK_P3[8] = {HEX(0x0e3426), HEX(0x349242), HEX(0x68c453), HEX(0x1e6038), HEX(0x95604f), HEX(0x6b4439), HEX(0xc07b66), HEX(0x402922)};  // old roots
static const u32 OAK_P4[8] = {HEX(0x18541e), HEX(0x60c836), HEX(0x96eb46), HEX(0x34962c), HEX(0xc07b66), HEX(0x6b4439), HEX(0x95604f), HEX(0x402922)};  // sapling
static const u32 OAK_P5[6] = {HEX(0x4c3a31), HEX(0x2e221e), HEX(0x705a4c), HEX(0x96806e), HEX(0xa06a34), HEX(0x825428)};  // dead

struct OakVar { int w, h, ax, ay, weight; const u32* pal; const char* const* rows; int sw, sh, sdx, sdy; int grass; };
// weight = how common this look is among oaks (adds up to 100). ax, ay = the foot of the trunk.
// sw, sh = size of the ground shadow. sdx, sdy = how far its centre sits from the foot of the trunk (right, down).
// grass = which grass sprite goes around the roots (a GRASS_* number from tree_grass.hpp).
static const OakVar OAK_VAR[OAK_VARIANTS] = {
    {50, 58, 24, 58, 26, OAK_P0, OAK_F_OAK, 40, 12, 2, -3, GRASS_OAK},  // lime
    {50, 58, 24, 58, 20, OAK_P1, OAK_F_OAK, 40, 12, 2, -3, GRASS_OAK},  // deep
    {50, 58, 24, 58, 18, OAK_P2, OAK_F_OAK, 40, 12, 2, -3, GRASS_OAK},  // soft
    {72, 94, 49, 94, 12, OAK_P3, OAK_F_OLD, 77, 13, -12, -6, GRASS_OLD},  // old roots
    {23, 24, 9, 24, 14, OAK_P4, OAK_F_SAPLING, 17, 5, 2, 0, GRASS_SAPLING},  // sapling
    {47, 49, 22, 49, 10, OAK_P5, OAK_F_DEAD, 37, 9, 2, -2, GRASS_DEAD},  // dead
};

inline Img mkOakFrame(int variant, int frame) {
    const OakVar& v = OAK_VAR[variant < 0 || variant >= OAK_VARIANTS ? 0 : variant];
    Img im(v.w, v.h);
    for (int y = 0; y < v.h; y++) {
        const char* row = v.rows[(frame % OAK_FRAMES) * v.h + y];
        for (int x = 0; x < v.w; x++)
            if (row[x] != '.') im.set(x, y, v.pal[row[x] - 'a']);
    }
    return im;
}

// Which look a tree at tile (tx, ty) gets. Fixed per tree, so it never changes between runs or saves.
inline int oakVariantFor(int tx, int ty) {
    unsigned h = ((unsigned)tx * 73856093u) ^ ((unsigned)ty * 19349663u);
    h ^= h >> 13; h *= 0x5bd1e995u; h ^= h >> 15;
    int roll = (int)(h % 100u);
    for (int i = 0; i < OAK_VARIANTS; i++) { roll -= OAK_VAR[i].weight; if (roll < 0) return i; }
    return 0;
}
